import { io } from "socket.io-client";

const SOCKET_URL = process.env.REACT_APP_SOCKET_URL || "http://localhost:5000";

// Single shared socket instance for the whole app - created lazily so
// we don't open a connection before the component tree mounts.
export const socket = io(SOCKET_URL, {
  autoConnect: true,
  reconnection: true,
});
